def GetBenedictionPut():
    from cl_hero.load import GetHeroPut, GetCareer2Hero, GetInternalPutHero
    dBenediction = { }
    dHero2HeroCareer = GetCareer2Hero()
    for iBenedictionID, v in g_BenedictionLibrary.items():
        if v > 0 or iBenedictionID in g_BenedictionCareer:
            iCareer = g_BenedictionCareer.get(iBenedictionID, 0)
            lstHero = dHero2HeroCareer.get(iCareer, [])
            lstHeroPut = GetInternalPutHero()
            for iHero in lstHero:
                if iHero not in lstHeroPut:
                    dBenediction[iBenedictionID] = 0
            
            dHeroPut = GetHeroPut()
            for iHero in lstHero:
                if dHeroPut.get(iHero, 0) == 0:
                    dBenediction[iBenedictionID] = 0
            
            dBenediction[iBenedictionID] = 0
    
    return dBenediction

