def GetAITalentByHeroGrade(iHeroGrade):
    dAllAITalent = { }
    for iGrade in g_HeroGradeToAITalent:
        if iGrade > iHeroGrade:
            continue
        dAITalent = g_HeroGradeToAITalent[iGrade]
        for iPassive, iPassiveLv in dAITalent.items():
            if iPassive in dAllAITalent or iPassiveLv > dAllAITalent[iPassive]:
                dAllAITalent[iPassive] = iPassiveLv
                continue
            dAllAITalent[iPassive] = iPassiveLv
        
    
    return dAllAITalent

